const fs=require('node:fs'),path=require('node:path');
const root=__dirname;
module.exports=function installStudyHub(html,seed){
 const marker='ielts48-study-hub-v1';
 const files=['planner-model.js','experience-v2.js','academic-evidence.js','polish-v3.js','study-hub.js','grouped-view.js','submission-status.js','compact-class.js','master-model.js','review-format.js','master-view.js'];
 const code=files.map(f=>fs.readFileSync(path.join(root,f),'utf8')).join('\n');
 const css=['study-hub.css','grouped-view.css','compact-class.css','experience-v2.css','polish-v3.css','master-view.css'].map(f=>fs.readFileSync(path.join(root,f),'utf8')).join('\n');
 if(code.includes('</script'))throw Error('UNSAFE_STUDY_HUB_SCRIPT');
 if(!seed){const p=path.join(root,'public/academic-leaderboard.json');if(fs.existsSync(p))seed=JSON.parse(fs.readFileSync(p,'utf8'));}
 if(!seed)throw Error('ACADEMIC_SEED_REQUIRED');
 const bundle='<style id="ielts48-study-hub-style">'+css+'</style><script id="ielts48-academic-seed" type="application/json">'+JSON.stringify(seed).replace(/</g,'\\u003c')+'</script><script id="'+marker+'">'+code+'</script>';
 const old=/<style id="ielts48-study-hub-style">[\s\S]*?<script id="ielts48-study-hub-v1">[\s\S]*?<\/script>/;
 if(old.test(html))html=html.replace(old,()=>bundle);else html=html.replace('</head>',bundle+'</head>');
 if(!html.includes('data-tab="planner"')){
  const schedule=/<button class="tab is-active" data-tab="schedule">Lịch học<\/button>/;
  if(!schedule.test(html))throw Error('STUDY_HUB_NAV_MISSING');
  html=html.replace(schedule,match=>match+'<button class="tab" data-tab="planner">Thời gian biểu</button>');
  html=html.replace(/<button class="tab" data-tab="overview">/, '<button class="tab" data-tab="leaderboard">Xếp hạng lớp</button><button class="tab" data-tab="overview">');
  html=html.replace(/<section id="panel-schedule" class="panel"><\/section>/,match=>match+'<section id="panel-planner" class="panel" hidden></section>');
  html=html.replace(/<section id="panel-overview"/, '<section id="panel-leaderboard" class="panel" hidden></section><section id="panel-overview"');
 }
 if(!html.includes('/* IELTS48_STUDY_HUB_INSTALL_V1 */')){
  const entry='ielts48InitCompactEmbedV29_();';
  if(html.split(entry).length!==2)throw Error('STUDY_HUB_ENTRY_AMBIGUOUS');
  const setup=`/* IELTS48_STUDY_HUB_INSTALL_V1 */IeltsStudyHub.install({getState:()=>state,access:ieltsParentAccess,preserve:fn=>IeltsStableView.update(IeltsStableView.capture(),fn),activate:tab=>activateTab(tab),wrapTab:fn=>{const original=renderTab;renderTab=function(tab){if(!fn(tab))return original.apply(this,arguments)}},wrapRefresh:fn=>{const original=renderAllPersonal;renderAllPersonal=function(){if(["planner","leaderboard"].includes(state.active)){fn();setTimeout(ielts48RenderPendingHomeworkV32_,0);return}original.apply(this,arguments);fn()}},adapters:{includeAssignment:item=>ielts48AssignmentEligibleForStudentV35_(state.student,item)&&!ielts48NoHomeworkItemV22_(item)&&(item.skill!=='speaking'||ielts48SpeakingAssignmentForStudent_(item)),includeLesson:event=>ielts48ScheduleForStudentV27_([event]).length>0,links:item=>(item.tasks||[]).flatMap(task=>[{title:task.title,url:parentLearningUrl_(task.url)},...(task.actions||[]).map(action=>({title:action.label||task.title,url:parentLearningUrl_(action.url)}))]).filter(link=>link.url),status:item=>{const record=ielts48RecordForAssignment_(item),known=parentSubmissionKnown_(item,record),deadline=item.directDeadline||record&&record.directDeadline,direct=item.directSubmission||record&&record.directSubmission;if(deadline&&parentSubmissionGuard_.can(item)){return {submitted:deadline.complete===true,confirmed:true,late:deadline.late===true,submittedAt:direct&&direct.latestSubmittedAt}}if(known&&(direct&&direct.complete===true||record&&(record.submitted===true||record.statusType==='done')))return {submitted:true,confirmed:true,submittedAt:record&&record.submittedAt};return {submitted:null,confirmed:false}}}});`;
  html=html.replace(entry,()=>setup+entry);
 }
 if(!html.includes('/* IELTS48_GROUPS_V1 */')){const hook='ielts48InitCompactEmbedV29_();';html=html.replace(hook,()=>'/* IELTS48_GROUPS_V1 */Ielts48Grouped.install({getState:()=>state,original:activateTab,render:tab=>renderTab(tab),wrapActivate:fn=>{const base=activateTab;activateTab=function(tab){return fn(tab,base)}}});'+hook);}
 html=html.replaceAll('if(old)el.open=old.open;','if(old&&el.open!==old.open)el.open=old.open;');
 if(!html.includes('/* IELTS48_COMPACT_V1 */')){html=html.replace('ielts48InitCompactEmbedV29_();',()=>`/* IELTS48_COMPACT_V1 */Ielts48Compact.install({getState:()=>state,access:ieltsParentAccess,pending:()=>ielts48PendingHomeworkEntriesV32_(),openPending:()=>ielts48OpenPendingHomeworkV32_(),activate:tab=>activateTab(tab),status:()=>{parentSubmissionLabel_=(item,record)=>IeltsSubmissionStatus.read(item,record).label;IeltsStudyHub.useStatus(item=>IeltsSubmissionStatus.read(item,ielts48RecordForAssignment_(item)));parentSubmissionLinks_=(item,record)=>parentSubmissionProblem_(item,record)+parentSubmissionButtons_((item.directSubmission||record&&record.directSubmission||{}).links);},wrap:fn=>{const base=renderAllPersonal;renderAllPersonal=function(){const result=base.apply(this,arguments);fn();return result;}}});ielts48InitCompactEmbedV29_();`);}
 html=html.replaceAll('label:parentSubmissionLabel_','label:(item,record)=>parentSubmissionLabel_(item,record)');
 if(!html.includes('/* IELTS48_EXPERIENCE_V2 */'))html=html.replace('ielts48InitCompactEmbedV29_();',()=>`/* IELTS48_EXPERIENCE_V2 */(function(){const base=ielts48PendingHomeworkEntriesV32_;ielts48PendingHomeworkEntriesV32_=function(){return base.apply(this,arguments).filter(entry=>{try{const item=[...(state.dashboard?.assignments||[]),...(state.dashboard?.shadowingAssignments||[])].find(a=>a.id===entry.id);return !item||!IeltsSubmissionStatus.read(item,ielts48RecordForAssignment_(item)).submitted;}catch(_){return true;}});};})();ielts48InitCompactEmbedV29_();`);
 if(!html.includes('/* IELTS48_POLISH_V3 */'))html=html.replace('ielts48InitCompactEmbedV29_();',()=>`/* IELTS48_POLISH_V3 */Ielts48Polish.install({getState:()=>state,events:()=>ielts48ScheduleForStudentV27_(state.dashboard?.lessonEvents||[]),reminders:()=>ielts48ScheduleForStudentV27_((state.dashboard?.assessmentReminders||[]).filter(ielts48OfficialAssessmentReminderV22_)),assessmentKey:item=>ielts48OfficialAssessmentKeyV23_(item),refreshResults:()=>renderOverview(),render:html=>{document.getElementById('panel-schedule').innerHTML=html;},wrap:fn=>{renderSchedule=fn;}});ielts48InitCompactEmbedV29_();`);
 // Exact UI phrases only: do not replace normalized parser tokens, names or lesson/feedback payloads.
 html=html.replaceAll('của con','của em').replaceAll('CỦA CON','CỦA EM').replaceAll('Cùng con','Cùng em').replaceAll('Chọn tên con','Chọn tên em');
 html=html.replaceAll("host.insertAdjacentHTML('beforeend',overviewHtml())","Ielts48Polish.updateWriting(host,overviewHtml())");
 if(!html.includes('/* IELTS48_MASTER_V4 */'))html=html.replace('ielts48InitCompactEmbedV29_();',()=>`/* IELTS48_MASTER_V4 */Ielts48Master.install({getState:()=>state,resolve:item=>IeltsDirectAssignmentResolver.resolve(item),record:item=>ielts48RecordForAssignment_(item),render:skill=>Ielts48Master.withNative(()=>renderTab(skill)),refreshNative:()=>renderAllPersonal(),wrap:fn=>{const base=renderAllPersonal;renderAllPersonal=function(){if(!Ielts48Master.isOpen())base.apply(this,arguments);fn();};}});ielts48InitCompactEmbedV29_();`);
 if(!html.includes('/* IELTS48_LAZY_DETAIL_V4 */'))html=html.replace('ielts48InitCompactEmbedV29_();',()=>`/* IELTS48_LAZY_DETAIL_V4 */(function(){const skill=renderSkill,shadow=renderIeltsShadowingV1_,overview=renderOverview;renderSkill=function(){if(Ielts48Master.nativeReady())return skill.apply(this,arguments);};renderIeltsShadowingV1_=function(){if(Ielts48Master.nativeReady())return shadow.apply(this,arguments);};renderOverview=function(){if(state.active==='overview')return overview.apply(this,arguments);};})();ielts48InitCompactEmbedV29_();`);
 html=html.replaceAll('render:skill=>renderTab(skill),refreshNative:()=>renderAllPersonal()','render:skill=>Ielts48Master.withNative(()=>renderTab(skill)),refreshNative:()=>renderAllPersonal()');
 // Classwork can arrive after the native Writing card has moved into its open detail dialog.
 html=html.replaceAll('mount(document.querySelector("#panel-writing"))','mount(document.querySelector(\'#ielts48-master-detail[open][data-master-skill="writing"] .master-native-detail\')||document.querySelector("#panel-writing"))');
 if(!html.includes('/* IELTS48_PRESENTATION_V6 */'))html=html.replace('ielts48InitCompactEmbedV29_();',()=>`/* IELTS48_PRESENTATION_V6 */(function(){const feedback=ielts48FeedbackHtmlV15_,record=overviewRecord;ielts48FeedbackHtmlV15_=function(text,...args){return Ielts48ReviewFormat.hasMarkers(text)?Ielts48ReviewFormat.writing(text,line=>feedback(line,...args)):feedback(text,...args);};overviewRecord=function(){return Ielts48ReviewFormat.html(record.apply(this,arguments));};})();ielts48InitCompactEmbedV29_();`);
 return html;
};
